      continue
    }

    // Try to read as a definition
    const def = readDefinition(line)
    if (def === undefined) {
      fail(`${path}: line ${i + 1}: expected [label]: <url>`)
    }

    // Add the definition
    try {
      define(definitions, i + 1, def, 'file')
    } catch (error) {
