/** The definitions one file carries, refused at its own line when a line is not a definition. */
function fileDefinitions(path) {
  let content
  try {
    content = readFileSync(path, 'utf8')
  } catch (error) {
    fail(`cannot read definitions ${path}`)
  }

  const definitions = new Map()
  const lines = content.split('\n')

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    const trimmed = line.trim()

    // Skip empty lines and comments
    if (trimmed === '' || trimmed.startsWith('#')) {
      continue
    }

    // Try to read as a definition
    const def = readDefinition(line)
    if (def === undefined) {
      fail(`${path}: line ${i + 1}: expected [label]: <url>`)
    }

    // Add the definition
    try {
      define(definitions, i + 1, def, 'file')
    } catch (error) {
      if (error instanceof RefError) {
        fail(`${path}: line ${error.line}: ${error.message}`)
      }
      throw error
    }
  }

  return definitions
}

const argv = process.argv.slice(2)
